import{_ as a,c as o,a2 as l,o as i}from"./chunks/framework.GMKO7RMU.js";const u=JSON.parse('{"title":"隐私政策","description":"Sean何为势网站隐私政策，说明 Cookie、Google AdSense 广告及个人信息处理方式。","frontmatter":{"layout":"doc","title":"隐私政策","description":"Sean何为势网站隐私政策，说明 Cookie、Google AdSense 广告及个人信息处理方式。"},"headers":[],"relativePath":"about/privacy.md","filePath":"about/privacy.md","lastUpdated":1790919781000}'),t={name:"about/privacy.md"};function r(n,e,s,h,d,p){return i(),o("div",null,e[0]||(e[0]=[l('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p>更新日期：2026-10-02<br> 适用网站：本站（含 amusi755.com 及相关镜像站点）</p><p>本隐私政策说明 Sean（何为势）运营的个人技术博客 / 服务介绍站点如何收集、使用与保护您的信息。继续访问本站，即表示您知悉本政策内容。</p><h2 id="_1-我们是谁" tabindex="-1">1. 我们是谁 <a class="header-anchor" href="#_1-我们是谁" aria-label="Permalink to &quot;1. 我们是谁&quot;">​</a></h2><p>本站由独立开发者 Sean（何为势）运营，用于分享技术内容、产品与服务信息。如需联系，请访问 <a href="/about/business.html">业务介绍</a>。</p><h2 id="_2-我们可能收集的信息" tabindex="-1">2. 我们可能收集的信息 <a class="header-anchor" href="#_2-我们可能收集的信息" aria-label="Permalink to &quot;2. 我们可能收集的信息&quot;">​</a></h2><p>在正常浏览过程中，本站或第三方服务可能处理以下信息：</p><ul><li><strong>访问日志类信息</strong>：如 IP 地址、浏览器类型、设备信息、访问时间、来源页面、浏览页面等（通常由托管商或 CDN 自动记录）</li><li><strong>Cookie 与类似技术</strong>：用于记住偏好、统计访问、展示广告等</li><li><strong>您主动提供的信息</strong>：例如通过微信等方式咨询业务时留下的联系方式与沟通内容</li></ul><p>我们不会要求您注册账号才能阅读公开文章。</p><h2 id="_3-cookie-与广告-google-adsense" tabindex="-1">3. Cookie 与广告（Google AdSense） <a class="header-anchor" href="#_3-cookie-与广告-google-adsense" aria-label="Permalink to &quot;3. Cookie 与广告（Google AdSense）&quot;">​</a></h2><p>本站使用 <strong>Google AdSense</strong> 展示广告（含自动广告）。Google 及其合作伙伴可能使用 Cookie 或类似技术：</p><ul><li>根据您的访问情况展示广告</li><li>衡量广告效果</li><li>在符合当地法律的前提下提供个性化或非个性化广告</li></ul><p>您可以通过浏览器设置管理或删除 Cookie。若您位于欧洲经济区、英国或瑞士等地，本站可能展示 Google 提供的用户意见征求（同意）消息，以便您选择是否同意相关用途。</p><p>了解 Google 如何使用数据，可参阅：<a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google 隐私权政策</a> 以及 <a href="https://policies.google.com/technologies/partner-sites" target="_blank" rel="noreferrer">Google 如何在合作伙伴网站上使用数据</a>。</p><h2 id="_4-第三方服务" tabindex="-1">4. 第三方服务 <a class="header-anchor" href="#_4-第三方服务" aria-label="Permalink to &quot;4. 第三方服务&quot;">​</a></h2><p>为保障网站运行、统计或变现，本站可能使用以下类型的第三方服务：</p><ul><li>网站托管 / CDN / DNS</li><li>Google AdSense（广告）</li><li>Google 用户意见征求 / Funding Choices（如已启用）</li><li>GitHub 等代码托管相关外链（点击跳转后适用对方政策）</li></ul><p>第三方按其自身隐私政策处理数据，本站无法完全控制其行为。</p><h2 id="_5-信息用途" tabindex="-1">5. 信息用途 <a class="header-anchor" href="#_5-信息用途" aria-label="Permalink to &quot;5. 信息用途&quot;">​</a></h2><p>收集或处理的信息主要用于：</p><ul><li>提供、维护与改进网站内容与访问体验</li><li>展示广告并衡量效果</li><li>防止滥用、保障安全</li><li>回应您主动发起的业务咨询</li></ul><h2 id="_6-信息共享" tabindex="-1">6. 信息共享 <a class="header-anchor" href="#_6-信息共享" aria-label="Permalink to &quot;6. 信息共享&quot;">​</a></h2><p>我们不会出售您的个人信息。仅在以下情形可能共享必要信息：</p><ul><li>经您同意</li><li>为提供广告、托管等服务而必需的服务商处理</li><li>法律法规要求或有权机关依法提出要求</li></ul><h2 id="_7-数据安全与保存" tabindex="-1">7. 数据安全与保存 <a class="header-anchor" href="#_7-数据安全与保存" aria-label="Permalink to &quot;7. 数据安全与保存&quot;">​</a></h2><p>我们采取合理的技术与管理措施保护站点与沟通信息。受互联网传输特性限制，无法保证绝对安全。日志与第三方 Cookie 的保存周期取决于对应服务提供商的策略。</p><h2 id="_8-您的权利" tabindex="-1">8. 您的权利 <a class="header-anchor" href="#_8-您的权利" aria-label="Permalink to &quot;8. 您的权利&quot;">​</a></h2><p>在适用法律允许的范围内，您可以：</p><ul><li>通过浏览器拒绝或清除 Cookie</li><li>使用 Google 广告设置管理个性化广告：<a href="https://adssettings.google.com" target="_blank" rel="noreferrer">https://adssettings.google.com</a></li><li>就本站隐私问题通过 <a href="/about/business.html">业务介绍</a> 中的联系方式与我们沟通</li></ul><h2 id="_9-儿童隐私" tabindex="-1">9. 儿童隐私 <a class="header-anchor" href="#_9-儿童隐私" aria-label="Permalink to &quot;9. 儿童隐私&quot;">​</a></h2><p>本站内容主要面向具备独立判断能力的成年读者与专业用户，不面向儿童提供服务。若您是监护人并认为儿童向我们提供了个人信息，请联系我们处理。</p><h2 id="_10-政策更新" tabindex="-1">10. 政策更新 <a class="header-anchor" href="#_10-政策更新" aria-label="Permalink to &quot;10. 政策更新&quot;">​</a></h2><p>我们可能不时更新本隐私政策。更新后会在本页面调整「更新日期」。重大变更时，建议您重新阅读本页。</p><h2 id="_11-联系我们" tabindex="-1">11. 联系我们 <a class="header-anchor" href="#_11-联系我们" aria-label="Permalink to &quot;11. 联系我们&quot;">​</a></h2><p>如对本隐私政策有任何疑问，请通过 <a href="/about/business.html">业务介绍 / 微信名片</a> 与 Sean 联系。</p>',35)]))}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
